def make_palindrome(string: str) -> str:
    """ Find the shortest palindrome that begins with a supplied string.
    Algorithm idea is simple:
    - Find the longest postfix of supplied string that is a palindrome.
    - Append to the end of the string reverse of a string prefix that comes before the palindromic suffix.
    >>> make_palindrome('')
    ''
    >>> make_palindrome('cat')
    'catac'
    >>> make_palindrome('cata')
    'catac'
    """
    def is_palindrome(string: str) -> bool:
        """ Test if given string is a palindrome """
        return string == string[::-1]

    def find_longest_palindrome(string: str) -> str:
        longest_palindrome = ""
        for i in range(len(string)):
            for j in range(len(string) - i):
                if is_palindrome(string[j:i + 1]):
                    longest_palindrome = string[j:i + 1]
                    break
        return longest_palindrome

    def create_palindrome(string: str) -> str:
        reversed_string = string[::-1]
        for i in range(len(string)):
            for j in range(len(string) - i):
                if is_palindrome(string[:j + 1] + reversed_string[i:]):
                    return string[:j + 1] + reversed_string[i:]

    longest_palindrome = find_longest_palindrome(string)
    if longest_palindrome == "":
        return string
    else:
        return create_palindrome(longest_palindrome)

