def parse_nested_parens(paren_string: str) -> List[int]:
    def get_max_depth(current_depth, max_depth):
        max_depth[0] = max(max_depth[0], current_depth)
        return max_depth[0]

    def parse_parens(s):
        stack = []
        current_depth = 0
        max_depth = [0]
        for char in s:
            if char == '(':
                stack.append(char)
                current_depth += 1
                get_max_depth(current_depth, max_depth)
            elif char == ')':
                stack.pop()
                current_depth -= 1
                get_max_depth(current_depth, max_depth)
        return max_depth[0]

    return [parse_parens(s) for s in paren_string.split()]

